import { db } from "@tepian-k3/db/client";
import {
  pelatihanEnrollments,
  pelatihanSchedules,
  pelatihanAttendances,
} from "@tepian-k3/db/schema";
import { and, eq, isNull, asc } from "@tepian-k3/db";
import { logError } from "@tepian-k3/services/logger";
import { TRPCError } from "@trpc/server";
import { Effect } from "effect";

export const getBimtekSchedules = (enrollmentId: string, userId: string) =>
  Effect.gen(function* () {
    const result = yield* Effect.tryPromise({
      try: () =>
        db.transaction(async (tx) => {
          // 1. Verify enrollment and ownership
          const enrollment = await tx.query.pelatihanEnrollments.findFirst({
            where: and(
              eq(pelatihanEnrollments.id, enrollmentId),
              eq(pelatihanEnrollments.userId, userId),
              isNull(pelatihanEnrollments.deletedAt)
            ),
            with: {
              pelatihan: true,
            },
          });

          if (!enrollment) {
            throw new TRPCError({
              code: "NOT_FOUND",
              message: "Pendaftaran pelatihan tidak ditemukan atau Anda tidak memiliki akses",
            });
          }

          // 2. Fetch all schedules for this pelatihan
          const schedules = await tx.query.pelatihanSchedules.findMany({
            where: and(
              eq(pelatihanSchedules.pelatihanId, enrollment.pelatihanId),
              isNull(pelatihanSchedules.deletedAt)
            ),
            orderBy: [
              asc(pelatihanSchedules.sessionDate),
              asc(pelatihanSchedules.startTime),
            ],
          });

          // 3. Fetch attendances for this enrollment
          const attendances = await tx.query.pelatihanAttendances.findMany({
            where: and(
              eq(pelatihanAttendances.enrollmentId, enrollmentId),
              isNull(pelatihanAttendances.deletedAt)
            ),
          });

          // 4. Map schedules with user's attendance status
          const schedulesWithAttendance = schedules.map((schedule) => {
            const att = attendances.find((a) => a.scheduleId === schedule.id);
            return {
              ...schedule,
              attendance: att
                ? {
                    id: att.id,
                    status: att.status,
                    checkedInAt: att.checkedInAt,
                  }
                : null,
            };
          });

          // 5. Calculate statistics
          const totalSchedules = schedules.length;
          const attendedSessions = attendances.filter(
            (a) => a.status === "present" || a.status === "excused"
          );
          const attendedCount = attendedSessions.length;
          const attendancePercentage =
            totalSchedules > 0
              ? Math.round((attendedCount / totalSchedules) * 100)
              : 0;

          return {
            schedules: schedulesWithAttendance,
            stats: {
              totalSchedules,
              attendedCount,
              attendancePercentage,
            },
            enrollment,
          };
        }),
      catch: (error) => {
        if (error instanceof TRPCError) throw error;
        logError("scheduleQueries.getBimtekSchedules", "Failed to fetch schedules", {
          error,
          enrollmentId,
          userId,
        });
        throw new TRPCError({
          code: "INTERNAL_SERVER_ERROR",
          message: "Gagal mengambil jadwal dan presensi",
        });
      },
    });

    return result;
  });

export const checkInBimtek = (
  enrollmentId: string,
  scheduleId: string,
  status: "present" | "excused",
  userId: string
) =>
  Effect.gen(function* () {
    const result = yield* Effect.tryPromise({
      try: () =>
        db.transaction(async (tx) => {
          // 1. Verify enrollment and ownership
          const enrollment = await tx.query.pelatihanEnrollments.findFirst({
            where: and(
              eq(pelatihanEnrollments.id, enrollmentId),
              eq(pelatihanEnrollments.userId, userId),
              isNull(pelatihanEnrollments.deletedAt)
            ),
          });

          if (!enrollment) {
            throw new TRPCError({
              code: "NOT_FOUND",
              message: "Pendaftaran pelatihan tidak ditemukan atau Anda tidak memiliki akses",
            });
          }

          // 2. Verify schedule exists and belongs to the pelatihan
          const schedule = await tx.query.pelatihanSchedules.findFirst({
            where: and(
              eq(pelatihanSchedules.id, scheduleId),
              eq(pelatihanSchedules.pelatihanId, enrollment.pelatihanId),
              isNull(pelatihanSchedules.deletedAt)
            ),
          });

          if (!schedule) {
            throw new TRPCError({
              code: "BAD_REQUEST",
              message: "Jadwal sesi tidak valid atau tidak sesuai dengan kelas pelatihan ini",
            });
          }

          // 3. Insert or update attendance log
          const existing = await tx.query.pelatihanAttendances.findFirst({
            where: and(
              eq(pelatihanAttendances.enrollmentId, enrollmentId),
              eq(pelatihanAttendances.scheduleId, scheduleId),
              isNull(pelatihanAttendances.deletedAt)
            ),
          });

          if (existing) {
            const [updated] = await tx
              .update(pelatihanAttendances)
              .set({
                status,
                updatedAt: new Date().toISOString(),
              })
              .where(eq(pelatihanAttendances.id, existing.id))
              .returning();
            return updated;
          } else {
            const [inserted] = await tx
              .insert(pelatihanAttendances)
              .values({
                enrollmentId,
                scheduleId,
                status,
              })
              .returning();
            return inserted;
          }
        }),
      catch: (error) => {
        if (error instanceof TRPCError) throw error;
        logError("scheduleQueries.checkInBimtek", "Failed to check-in attendance", {
          error,
          enrollmentId,
          scheduleId,
          status,
          userId,
        });
        throw new TRPCError({
          code: "INTERNAL_SERVER_ERROR",
          message: "Gagal menyimpan presensi Anda",
        });
      },
    });

    return result;
  });

const scheduleQueries = {
  getBimtekSchedules,
  checkInBimtek,
};

export default scheduleQueries;

